import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import type {ConnectionProfile} from '../../packages/protocol/src/index.js';
import {ConnectionManager} from '../../packages/core/src/connections.js';
import {SqlDocuments} from '../../packages/core/src/sql-documents.js';
import {QueryPlans} from '../../packages/core/src/query-plans.js';
export async function queryPlanContract(profile:ConnectionProfile,password:string){
 const ro={...profile,id:profile.id+'-plan-readonly',readOnly:true},manager=new ConnectionManager({list:()=>[profile,ro],save:async()=>{},remove:async()=>{}},{runnerPath:'unused'}),documents=new SqlDocuments(manager),plans=new QueryPlans(manager,documents),owner='plan-contract.sql',table='plan_'+randomUUID().replaceAll('-','').slice(0,12),pg=profile.driver==='postgresql';
 try{await manager.setPassword(profile.id,password,'session');await manager.setPassword(ro.id,password,'session');const admin=await manager.connect(profile.id);await admin.query(`CREATE TABLE ${table}(id INT PRIMARY KEY,v INT)`);await admin.query(`INSERT INTO ${table} VALUES(1,7)`);
  try{
   await documents.bind(owner,profile.id);if(pg)await assert.rejects(documents.execute(owner,'SELECT definitely_missing_column'),e=>(e as {position?:string}).position==='8');else await assert.rejects(documents.execute(owner,'SELECT FROM'),e=>/at line 1/.test((e as {sqlMessage?:string}).sqlMessage??''));await documents.execute(owner,'CREATE TEMPORARY TABLE plan_temp(id INT)');const explain=await plans.run((await plans.prepare(owner,'SELECT * FROM plan_temp','explain')).token);assert(explain.nodes.length,explain.warnings.join(';'));assert(explain.raw.includes('plan_temp'));assert.equal(explain.mode,'explain');
   const onlyPlan=await plans.run((await plans.prepare(owner,`UPDATE ${table} SET v=11 WHERE id=1`,'explain')).token);assert(onlyPlan.nodes.length);assert.equal((await admin.query(`SELECT v FROM ${table}`)).rows[0]?.c0,7);
   const analysis=await plans.prepare(owner,`SELECT * FROM ${table} WHERE id=1`,'analyze');await assert.rejects(plans.run(analysis.token),/confirmation/);const report=await plans.run(analysis.token,true);assert(report.nodes.length,report.warnings.join(';'));assert.match(report.raw,pg?/Actual Rows/:profile.driver==='mariadb'?/r_rows/:/actual time=/);assert(report.warnings.some(w=>w.includes('executed')));
   if(profile.driver!=='mysql'){await documents.transaction(owner,'begin');const update=await plans.run((await plans.prepare(owner,`UPDATE ${table} SET v=19 WHERE id=1`,'analyze')).token,true);assert.equal(update.transactionAfter,'active');assert.equal((await documents.execute(owner,`SELECT v FROM ${table}`)).rows[0]?.c0,19);assert.equal((await admin.query(`SELECT v FROM ${table}`)).rows[0]?.c0,7);await documents.transaction(owner,'rollback');assert.equal((await admin.query(`SELECT v FROM ${table}`)).rows[0]?.c0,7);}
   const stale=await plans.prepare(owner,'SELECT 1','analyze');await manager.documentSession(owner)!.query(pg?'SET search_path TO pg_catalog':'USE information_schema');await assert.rejects(plans.run(stale.token,true),/search path/);await documents.execute(owner,pg?'SET search_path TO public':'USE dbworkbench');
   await documents.bind('readonly-plan.sql',ro.id);const readonly=await plans.run((await plans.prepare('readonly-plan.sql',`SELECT * FROM ${table}`,'explain')).token);assert(readonly.nodes.length);const roAnalysis=await plans.prepare('readonly-plan.sql',`SELECT * FROM ${table}`,'analyze');assert((await plans.run(roAnalysis.token,true)).nodes.length);await assert.rejects(plans.prepare('readonly-plan.sql',`UPDATE ${table} SET v=99`,'analyze'),/Read-only/);assert.equal((await admin.query(`SELECT v FROM ${table}`)).rows[0]?.c0,7);
   const pid=String((await documents.execute(owner,pg?'SELECT pg_backend_pid()':'SELECT CONNECTION_ID()')).rows[0]!.c0);assert.match(pid,/^\d+$/);const activeSql=pg?`SELECT count(*) FROM pg_stat_activity WHERE pid=${pid} AND state='active' AND query LIKE '%pg_sleep%'`:`SELECT count(*) FROM information_schema.PROCESSLIST WHERE ID=${pid} AND COMMAND='Query' AND INFO LIKE '%SLEEP%'`;const slow=await plans.prepare(owner,pg?'SELECT pg_sleep(20)':'SELECT SLEEP(20)','analyze'),pending=plans.run(slow.token,true);const rejected=assert.rejects(pending);let running=false;for(let i=0;i<60;i++){if(Number((await admin.query(activeSql)).rows[0]?.c0)>0){running=true;break;}await new Promise(r=>setTimeout(r,50));}assert(running,'The slow statement must actually reach the server before cancellation');assert(await documents.cancel(owner));await rejected;let stopped=false;for(let i=0;i<40;i++){if(Number((await admin.query(activeSql)).rows[0]?.c0)===0){stopped=true;break;}await new Promise(r=>setTimeout(r,50));}if(!stopped)await admin.query(pg?`SELECT pg_terminate_backend(${pid})`:`KILL CONNECTION ${pid}`);assert(stopped,'Cancellation must stop the backend query, not only disconnect the UI');assert.equal(documents.state(owner).lost,true);await documents.reset(owner);assert.equal((await documents.execute(owner,'SELECT 1')).rows[0]?.c0,1);
  }finally{await admin.query(`DROP TABLE IF EXISTS ${table}`);}
 }finally{await manager.close();}
}
